Kept the heap in a vector with the largest value at index 0. Inserting a value moves it upward until its parent is larger. Removing the maximum replaces the root with the last value and moves it downward.

`changeKey` can move in either direction, so the code checks the new value against its parent first.

### Dry run
For values `10, 4, 15`, the heap becomes `[15, 4, 10]`. Removing the root places `10` at the front, then restores the heap as `[10, 4]`.

```cpp
#include <vector>
#include <algorithm>
using namespace std;

class Solution{
    vector<int> heap;

    void siftUp(int index) {
        while (index > 0) {
            int parent = (index - 1) / 2;
            if (heap[parent] >= heap[index]) {
                break;
            }
            swap(heap[parent], heap[index]);
            index = parent;
        }
    }

    void siftDown(int index) {
        int n = static_cast<int>(heap.size());

        while (true) {
            int largest = index;
            int left = 2 * index + 1;
            int right = 2 * index + 2;

            if (left < n && heap[left] > heap[largest]) {
                largest = left;
            }
            if (right < n && heap[right] > heap[largest]) {
                largest = right;
            }

            if (largest == index) {
                break;
            }

            swap(heap[index], heap[largest]);
            index = largest;
        }
    }

public:
    void initializeHeap(){
        heap.clear();
    }

    void insert(int key){
        heap.push_back(key);
        siftUp(static_cast<int>(heap.size()) - 1);
    }

    void changeKey(int index, int new_val){
        if (index < 0 || index >= static_cast<int>(heap.size())) {
            return;
        }

        heap[index] = new_val;
        if (index > 0 && heap[index] > heap[(index - 1) / 2]) {
            siftUp(index);
        } else {
            siftDown(index);
        }
    }

    void extractMax(){
        if (heap.empty()) {
            return;
        }

        heap[0] = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            siftDown(0);
        }
    }

    bool isEmpty(){
        return heap.empty();
    }

    int getMax(){
        return heap.empty() ? -1 : heap[0];
    }

    int heapSize(){
        return static_cast<int>(heap.size());
    }
};
