using System;
using System.Collections.Generic;

public class Solution {
    private readonly List<int> heap = new List<int>();

    public void initializeHeap() {
        heap.Clear();
    }

    public void insert(int key) {
        heap.Add(key);
        int index = heap.Count - 1;

        while (index > 0) {
            int parent = (index - 1) / 2;
            if (heap[parent] >= heap[index]) {
                break;
            }

            int temp = heap[parent];
            heap[parent] = heap[index];
            heap[index] = temp;
            index = parent;
        }
    }

    public void changeKey(int index, int new_val) {
        if (index < 0 || index >= heap.Count) {
            return;
        }

        heap[index] = new_val;
        if (index > 0 && heap[index] > heap[(index - 1) / 2]) {
            while (index > 0) {
                int parent = (index - 1) / 2;
                if (heap[parent] >= heap[index]) {
                    break;
                }

                int temp = heap[parent];
                heap[parent] = heap[index];
                heap[index] = temp;
                index = parent;
            }
            return;
        }

        while (true) {
            int largest = index;
            int left = 2 * index + 1;
            int right = 2 * index + 2;

            if (left < heap.Count && heap[left] > heap[largest]) {
                largest = left;
            }
            if (right < heap.Count && heap[right] > heap[largest]) {
                largest = right;
            }
            if (largest == index) {
                break;
            }

            int temp = heap[index];
            heap[index] = heap[largest];
            heap[largest] = temp;
            index = largest;
        }
    }

    public void extractMax() {
        if (heap.Count == 0) {
            return;
        }

        int last = heap.Count - 1;
        heap[0] = heap[last];
        heap.RemoveAt(last);

        int index = 0;
        while (true) {
            int largest = index;
            int left = 2 * index + 1;
            int right = 2 * index + 2;

            if (left < heap.Count && heap[left] > heap[largest]) {
                largest = left;
            }
            if (right < heap.Count && heap[right] > heap[largest]) {
                largest = right;
            }
            if (largest == index) {
                break;
            }

            int temp = heap[index];
            heap[index] = heap[largest];
            heap[largest] = temp;
            index = largest;
        }
    }

    public bool isEmpty() {
        return heap.Count == 0;
    }

    public int getMax() {
        return heap.Count == 0 ? -1 : heap[0];
    }

    public int heapSize() {
        return heap.Count;
    }
}
```

Only one path is changed during an update, so `insert`, `changeKey`, and `extractMax` take `O(log n)` time. The other methods are `O(1)`. The list uses `O(n)` space.

