import java.util.*;

class Solution {

    ArrayList<Integer> heap;

    public void initializeHeap() {
        heap = new ArrayList<>();
    }

    public void insert(int key) {
        heap.add(key);
        int i = heap.size() - 1;

        while (i > 0) {
            int parent = (i - 1) / 2;

            if (heap.get(parent) < heap.get(i)) {
                swap(parent, i);
                i = parent;
            } else {
                break;
            }
        }
    }

    public void changeKey(int index, int newVal) {
        if (index < 0 || index >= heap.size()) return;

        int oldVal = heap.get(index);
        heap.set(index, newVal);

        if (newVal > oldVal) {
            // Heapify Up
            while (index > 0) {
                int parent = (index - 1) / 2;

                if (heap.get(parent) < heap.get(index)) {
                    swap(parent, index);
                    index = parent;
                } else {
                    break;
                }
            }
        } else {
            // Heapify Down
            heapify(index);
        }
    }

    public void extractMax() {
        if (heap.isEmpty()) return;

        int last = heap.size() - 1;
        swap(0, last);
        heap.remove(last);

        if (!heap.isEmpty()) {
            heapify(0);
        }
    }

    public boolean isEmpty() {
        return heap.isEmpty();
    }

    public int getMax() {
        return heap.get(0);
    }

    public int heapSize() {
        return heap.size();
    }

    private void heapify(int i) {
        int n = heap.size();

        while (true) {
            int largest = i;
            int left = 2 * i + 1;
            int right = 2 * i + 2;

            if (left < n && heap.get(left) > heap.get(largest))
                largest = left;

            // Right is chosen only if strictly greater.
            // If equal, left remains selected.
            if (right < n && heap.get(right) > heap.get(largest))
                largest = right;

            if (largest == i)
                break;

            swap(i, largest);
            i = largest;
        }
    }

    private void swap(int i, int j) {
        int temp = heap.get(i);
        heap.set(i, heap.get(j));
        heap.set(j, temp);
    }
}
